using System.Security.Cryptography;
public static string calcSign(string timestamp, string encryptKey, string body) {
        StringBuilder content = new StringBuilder();
        content.Append(timestamp);
        content.Append(encryptKey);
        content.Append(body);
        SHA256 sha256 = new SHA256CryptoServiceProvider();  
        byte[] contentBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(content.ToString()));  
        string sign = BitConverter.ToString(contentBytes); 
        sign = sign.Replace("-", "");  
        return sign;  
}
